#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
enum ExternalStorageShallowCopyProjection {
    Identity,
    AnyArrayElement,
    ArrayRange {
        target_start: usize,
        source_start: usize,
        length: usize,
    },
    ArrayIndex {
        target_index: usize,
    },
}

impl ExternalStorageShallowCopy {
    fn map_suffix(&self, suffix: &[String]) -> Option<StaticAliasPath> {
        let property = suffix.first()?;
        if self
            .excluded
            .iter()
            .any(|excluded| suffix.starts_with(excluded))
        {
            return None;
        }
        let mut mapped_property = None;
        let remaining = match &self.projection {
            ExternalStorageShallowCopyProjection::Identity => suffix,
            ExternalStorageShallowCopyProjection::AnyArrayElement => {
                let index = property.parse::<usize>().ok()?;
                if index.to_string() != *property {
                    return None;
                }
                &suffix[1..]
            }
            ExternalStorageShallowCopyProjection::ArrayRange {
                target_start,
                source_start,
                length,
            } => {
                let index = property.parse::<usize>().ok()?;
                if index.to_string() != *property
                    || index < *target_start
                    || index >= target_start.saturating_add(*length)
                {
                    return None;
                }
                mapped_property = Some(
                    source_start
                        .saturating_add(index.saturating_sub(*target_start))
                        .to_string(),
                );
                &suffix[1..]
            }
            ExternalStorageShallowCopyProjection::ArrayIndex { target_index } => {
                let index = property.parse::<usize>().ok()?;
                if index.to_string() != *property || index != *target_index {
                    return None;
                }
                &suffix[1..]
            }
        };
        let mut candidate = self.source.clone();
        if let Some(property) = mapped_property {
            candidate.properties.push(property);
        }
        candidate.properties.extend_from_slice(remaining);
        Some(candidate.canonicalized())
    }
}

impl ExternalStorageFlowState {
    fn rebase_subtree_path(
        path: &StaticAliasPath,
        source: &StaticAliasPath,
        target: &StaticAliasPath,
    ) -> StaticAliasPath {
        if !path.starts_with(source) {
            return path.clone();
        }
        let mut rebased = target.clone();
        rebased
            .properties
            .extend_from_slice(&path.properties[source.properties.len()..]);
        rebased.element_wildcard |= path.element_wildcard;
        rebased.canonicalized()
    }

    fn snapshot_subtree(&mut self, target: &StaticAliasPath, source: &StaticAliasPath) {
        let aliases = self
            .aliases
            .iter()
            .filter(|(path, _)| path.starts_with(source))
            .map(|(path, candidates)| {
                (
                    Self::rebase_subtree_path(path, source, target),
                    candidates
                        .iter()
                        .map(|candidate| Self::rebase_subtree_path(candidate, source, target))
                        .collect::<BTreeSet<_>>(),
                )
            })
            .collect::<Vec<_>>();
        let retained_identity_origins = self
            .retained_identity_origins
            .iter()
            .filter(|(path, _)| path.starts_with(source))
            .map(|(path, origins)| {
                (
                    Self::rebase_subtree_path(path, source, target),
                    origins
                        .iter()
                        .map(|origin| Self::rebase_subtree_path(origin, source, target))
                        .collect::<BTreeSet<_>>(),
                )
            })
            .collect::<Vec<_>>();
        let attached_alias_roots = self
            .attached_alias_roots
            .iter()
            .filter(|(path, _)| path.starts_with(source))
            .map(|(path, roots)| {
                (
                    Self::rebase_subtree_path(path, source, target),
                    roots.clone(),
                )
            })
            .collect::<Vec<_>>();
        let shallow_copies = self
            .shallow_copies
            .iter()
            .filter(|(path, _)| path.starts_with(source))
            .map(|(path, copies)| {
                (
                    Self::rebase_subtree_path(path, source, target),
                    copies
                        .iter()
                        .cloned()
                        .map(|mut copy| {
                            copy.source = Self::rebase_subtree_path(&copy.source, source, target);
                            copy
                        })
                        .collect::<BTreeSet<_>>(),
                )
            })
            .collect::<Vec<_>>();
        for (path, candidates) in aliases {
            self.aliases.entry(path).or_default().extend(candidates);
        }
        for (path, origins) in retained_identity_origins {
            self.retained_identity_origins
                .entry(path)
                .or_default()
                .extend(origins);
        }
        for (path, roots) in attached_alias_roots {
            self.attached_alias_roots
                .entry(path)
                .or_default()
                .extend(roots);
        }
        for (path, copies) in shallow_copies {
            self.shallow_copies.entry(path).or_default().extend(copies);
        }
    }

    fn detach_shallow_copy_sources(
        &mut self,
        source: &StaticAliasPath,
        snapshot: &StaticAliasPath,
    ) {
        for (target, copies) in &mut self.shallow_copies {
            if target.starts_with(source) {
                continue;
            }
            *copies = std::mem::take(copies)
                .into_iter()
                .map(|mut copy| {
                    copy.source = Self::rebase_subtree_path(&copy.source, source, snapshot);
                    copy
                })
                .collect();
        }
    }

    fn merge(left: Self, right: Self) -> Self {
        let mut merged = left;
        for (target, sources) in right.aliases {
            merged.aliases.entry(target).or_default().extend(sources);
        }
        for (target, origins) in right.retained_identity_origins {
            merged
                .retained_identity_origins
                .entry(target)
                .or_default()
                .extend(origins);
        }
        for (target, roots) in right.attached_alias_roots {
            merged
                .attached_alias_roots
                .entry(target)
                .or_default()
                .extend(roots);
        }
        for (target, copies) in right.shallow_copies {
            merged
                .shallow_copies
                .entry(target)
                .or_default()
                .extend(copies);
        }
        merged.attached_parameters.extend(right.attached_parameters);
        merged
    }

    fn alias_candidates(&self, path: &StaticAliasPath) -> BTreeSet<StaticAliasPath> {
        let mut resolved = BTreeSet::new();
        let mut pending = VecDeque::from([path.clone()]);
        while let Some(current) = pending.pop_front() {
            if !resolved.insert(current.clone()) {
                continue;
            }
            for alias in resolve_historical_alias_paths(&self.aliases, &current) {
                if !resolved.contains(&alias) {
                    pending.push_back(alias);
                }
            }
            for origin in resolve_historical_alias_paths(&self.retained_identity_origins, &current)
            {
                if !resolved.contains(&origin) {
                    pending.push_back(origin);
                }
            }
            for (target, copies) in &self.shallow_copies {
                if !current.starts_with(target)
                    || current.properties.len() < target.properties.len().saturating_add(2)
                {
                    continue;
                }
                let suffix = &current.properties[target.properties.len()..];
                for copy in copies {
                    if let Some(mut candidate) = copy.map_suffix(suffix) {
                        candidate.element_wildcard |= current.element_wildcard;
                        pending.push_back(candidate);
                    }
                }
            }
        }
        resolved
    }

    fn attached_roots(&self, path: &StaticAliasPath) -> BTreeSet<SymbolId> {
        let mut roots = BTreeSet::new();
        for candidate in self.alias_candidates(path) {
            if let Some(root) = candidate.binding_root()
                && self.attached_parameters.contains(&root)
            {
                roots.insert(root);
            }
            for (target, attached) in &self.attached_alias_roots {
                if candidate.starts_with(target) {
                    roots.extend(attached);
                }
            }
            for (target, copies) in &self.shallow_copies {
                if candidate.starts_with(target)
                    && candidate.properties.len() >= target.properties.len().saturating_add(2)
                {
                    let suffix = &candidate.properties[target.properties.len()..];
                    for copy in copies {
                        if copy.map_suffix(suffix).is_some() {
                            roots.extend(&copy.attached_roots);
                        }
                    }
                }
            }
        }
        roots
    }

    fn storage_container_attached_roots(&self, path: &StaticAliasPath) -> BTreeSet<SymbolId> {
        let mut roots = self.attached_roots(path);
        for (target, copies) in &self.shallow_copies {
            if !path.starts_with(target)
                || path.properties.len() < target.properties.len().saturating_add(1)
            {
                continue;
            }
            let suffix = &path.properties[target.properties.len()..];
            for copy in copies {
                let Some(candidate) = copy.map_suffix(suffix) else {
                    continue;
                };
                roots.extend(&copy.attached_roots);
                roots.extend(self.attached_roots(&candidate));
            }
        }
        roots
    }

    fn clear_aliases(&mut self, path: &StaticAliasPath) {
        let attached_parent_roots = if path.properties.is_empty() {
            BTreeSet::new()
        } else {
            let mut parent = path.clone();
            parent.properties.pop();
            self.storage_container_attached_roots(&parent)
        };
        self.aliases.retain(|target, _| !target.overlaps(path));
        self.retained_identity_origins.retain(|target, origins| {
            if target.overlaps(path) {
                return false;
            }
            origins.retain(|origin| !origin.overlaps(path));
            !origins.is_empty()
        });
        self.attached_alias_roots
            .retain(|target, _| !target.overlaps(path));
        self.shallow_copies.retain(|target, copies| {
            if target.starts_with(path) {
                return false;
            }
            if path.starts_with(target) && path.properties.len() > target.properties.len() {
                let excluded = path.properties[target.properties.len()..].to_vec();
                *copies = std::mem::take(copies)
                    .into_iter()
                    .map(|mut copy| {
                        copy.excluded.insert(excluded.clone());
                        copy
                    })
                    .collect();
            }
            true
        });
        if !attached_parent_roots.is_empty() {
            self.attached_alias_roots
                .insert(path.clone(), attached_parent_roots);
        }
    }

    fn clear_array_element_copies(
        &mut self,
        target: &StaticAliasPath,
        precise_extent: Option<usize>,
    ) {
        let wildcard = target.with_element_wildcard();
        self.shallow_copies.retain(|copy_target, copies| {
            if wildcard.element_wildcard_matches(copy_target) {
                return false;
            }
            if copy_target != target {
                return true;
            }
            *copies = std::mem::take(copies)
                .into_iter()
                .filter_map(|mut copy| match copy.projection {
                    ExternalStorageShallowCopyProjection::Identity => {
                        let extent = precise_extent?;
                        copy.excluded
                            .extend((0..extent).map(|index| vec![index.to_string()]));
                        Some(copy)
                    }
                    ExternalStorageShallowCopyProjection::AnyArrayElement
                    | ExternalStorageShallowCopyProjection::ArrayRange { .. }
                    | ExternalStorageShallowCopyProjection::ArrayIndex { .. } => None,
                })
                .collect();
            !copies.is_empty()
        });
    }

    fn forget_deleted_path(&mut self, path: &StaticAliasPath) {
        self.clear_aliases(path);
        self.attached_alias_roots
            .retain(|target, _| !target.overlaps(path));
    }

    fn identity_origins(&self, path: &StaticAliasPath) -> BTreeSet<StaticAliasPath> {
        let mut origins = resolve_historical_alias_paths(&self.retained_identity_origins, path);
        origins.remove(&path.clone().canonicalized());
        origins
    }

    fn record_identity_move(
        &mut self,
        target: StaticAliasPath,
        origins: BTreeSet<StaticAliasPath>,
    ) {
        self.retained_identity_origins
            .entry(target)
            .or_default()
            .extend(origins);
    }

    fn insert_alias(
        &mut self,
        target: StaticAliasPath,
        candidates: BTreeSet<StaticAliasPath>,
        attached: BTreeSet<SymbolId>,
    ) {
        if !candidates.is_empty() {
            self.aliases.insert(target.clone(), candidates);
        }
        if !attached.is_empty() {
            self.attached_alias_roots.insert(target, attached);
        }
    }

    fn record_shallow_copy(
        &mut self,
        target: StaticAliasPath,
        source: &StaticAliasPath,
        excluded: BTreeSet<String>,
    ) {
        let attached_roots = self.attached_roots(source);
        for source in self.alias_candidates(source) {
            self.shallow_copies
                .entry(target.clone())
                .or_default()
                .insert(ExternalStorageShallowCopy {
                    source,
                    excluded: excluded
                        .iter()
                        .cloned()
                        .map(|property| vec![property])
                        .collect(),
                    attached_roots: attached_roots.clone(),
                    projection: ExternalStorageShallowCopyProjection::Identity,
                });
        }
    }

    fn record_array_range_copy(
        &mut self,
        target: StaticAliasPath,
        source: &StaticAliasPath,
        target_start: usize,
        source_start: usize,
        length: usize,
    ) {
        let attached_roots = self.attached_roots(source);
        for source in self.alias_candidates(source) {
            self.shallow_copies
                .entry(target.clone())
                .or_default()
                .insert(ExternalStorageShallowCopy {
                    source,
                    excluded: BTreeSet::new(),
                    attached_roots: attached_roots.clone(),
                    projection: ExternalStorageShallowCopyProjection::ArrayRange {
                        target_start,
                        source_start,
                        length,
                    },
                });
        }
    }

    fn record_array_index_copy(
        &mut self,
        target: StaticAliasPath,
        target_index: usize,
        source: &StaticAliasPath,
    ) {
        let attached_roots = self.attached_roots(source);
        for source in self.alias_candidates(source) {
            self.shallow_copies
                .entry(target.clone())
                .or_default()
                .insert(ExternalStorageShallowCopy {
                    source,
                    excluded: BTreeSet::new(),
                    attached_roots: attached_roots.clone(),
                    projection: ExternalStorageShallowCopyProjection::ArrayIndex { target_index },
                });
        }
    }

    fn record_array_element_copies(
        &mut self,
        target: StaticAliasPath,
        sources: impl IntoIterator<Item = StaticAliasPath>,
    ) {
        for source in sources {
            let attached_roots = self.attached_roots(&source);
            for source in self.alias_candidates(&source) {
                self.shallow_copies
                    .entry(target.clone())
                    .or_default()
                    .insert(ExternalStorageShallowCopy {
                        source,
                        excluded: BTreeSet::new(),
                        attached_roots: attached_roots.clone(),
                        projection: ExternalStorageShallowCopyProjection::AnyArrayElement,
                    });
            }
        }
    }

    fn record_opaque_array_elements(&mut self, target: StaticAliasPath) {
        self.record_array_element_copies(
            target,
            [StaticAliasPath::unresolved_global(
                "<opaque-array-element>".to_string(),
            )],
        );
    }

    fn record_opaque_result(&mut self, target: StaticAliasPath) {
        self.aliases
            .entry(target)
            .or_default()
            .insert(StaticAliasPath::unresolved_global(
                "<opaque-call-result>".to_string(),
            ));
    }
}

impl<'a> Visit<'a> for LocalCallableResultCollector<'_, '_> {
    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _function: &ArrowFunctionExpression<'a>) {}

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        if let Some(expression) = &statement.argument {
            self.results.extend(self.owner.local_callable_results(
                expression,
                self.lexical_receiver.as_ref(),
                self.function_depth,
            ));
        }
    }
}

impl<'a> Visit<'a> for ConstructorReplacementResultCollector<'_, '_> {
    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _function: &ArrowFunctionExpression<'a>) {}

    fn visit_class(&mut self, _class: &Class<'a>) {}

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        if let Some(expression) = &statement.argument
            && constructor_return_may_replace_instance(expression)
        {
            self.results.extend(self.owner.local_callable_results(
                expression,
                Some(&self.lexical_receiver),
                self.function_depth,
            ));
        }
    }
}

impl<'a> Visit<'a> for EscapedFunctionValueCollector<'_, '_> {
    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {}

    fn visit_arrow_function_expression(&mut self, _function: &ArrowFunctionExpression<'a>) {}

    fn visit_return_statement(&mut self, statement: &ReturnStatement<'a>) {
        if let Some(expression) = &statement.argument {
            self.owner
                .collect_exposed_argument_paths(expression, &mut self.paths);
        }
    }

    fn visit_yield_expression(&mut self, expression: &oxc::ast::ast::YieldExpression<'a>) {
        if let Some(argument) = &expression.argument {
            if expression.delegate {
                self.owner
                    .collect_spread_exposed_argument_paths(argument, &mut self.paths);
            } else {
                self.owner
                    .collect_exposed_argument_paths(argument, &mut self.paths);
            }
        }
    }
}

#[derive(Default)]
struct GeneratorSuspensionCollector {
    suspended: bool,
}

#[derive(Default)]
struct CallableValuePresenceCollector {
    found: bool,
}

impl<'a> Visit<'a> for CallableValuePresenceCollector {
    fn visit_function(&mut self, _function: &Function<'a>, _flags: ScopeFlags) {
        self.found = true;
    }

    fn visit_arrow_function_expression(&mut self, _function: &ArrowFunctionExpression<'a>) {
        self.found = true;
    }

    fn visit_class(&mut self, _class: &Class<'a>) {
        self.found = true;
    }
}

impl<'a> Visit<'a> for GeneratorSuspensionCollector {
    fn visit_yield_expression(&mut self, _expression: &oxc::ast::ast::YieldExpression<'a>) {
        self.suspended = true;
    }
}

fn has_linear_generator_segments(body: &FunctionBody<'_>) -> bool {
    for statement in &body.statements {
        if let Statement::ExpressionStatement(statement) = statement
            && let Expression::YieldExpression(expression) =
                statement.expression.get_inner_expression()
        {
            if expression.delegate {
                return false;
            }
            let mut nested = GeneratorSuspensionCollector::default();
            if let Some(argument) = &expression.argument {
                nested.visit_expression(argument);
            }
            if nested.suspended {
                return false;
            }
            continue;
        }
        let mut nested = GeneratorSuspensionCollector::default();
        nested.visit_statement(statement);
        if nested.suspended {
            return false;
        }
    }
    true
}

